"""
    Produce a list of integers corresponding to the number of times an
    element in the input list has been observed.

    Parameters
    ----------
    input_list : list
        list of values

    Returns
    -------
    occurrence : list
        integer list

    Examples
    --------

    unique_number_from_list(['a','a','b','c','c','c'])
    unique_number_from_list(['a','b','c'])

    """
def unique_number_from_list(input_list: Any) -> object {
    dups = {};
    occurrence = [];
    for (i, val) in enumerate(input_list) {
        if (val not in dups) {
            dups[val] = [i, 1];
        } else {
            dups[val][1] += 1;
        }
        occurrence.append(dups[val][1]);
    }
    return occurrence;
}

"""
    :param nums: number
    :return: number of translations
    """
def trans_nums_to_strs(nums: Any) -> object {
    nums = str(nums);
    cache = [1, 1];
    for i in range(1, len(nums)) {
        if (9 < int(nums[(i - 1):(i + 1)]) < 26) {
            (cache[1], cache[0]) = ((cache[0] + cache[1]), cache[1]);
        } else {
            cache[0] = cache[1];
        }
    }
    return cache[1];
}

