"""Function to calculate MOA and DCC metric

    Args:
        variables (list): [description]
        classes (list): [description]
        noc (int): [description]

    Returns:
        result: [description]
    """
def calculate_MOA_or_DCC(variables: Any, classes: Any, noc: Any) -> object {
    res = 0;
    for i in variables {
        if (i in classes) {
            res += 1;
        }
    }
    return (res / noc);
}
